import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

cat4d_cuda_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <vector>

__global__ void cat4d_kernel(
    const float* in1, const float* in2, const float* in3, const float* in4,
    float* out,
    int N, int C1, int C2, int C3, int C4,
    int H, int W
) {
    int index = blockIdx.x * blockDim.x + threadIdx.x;
    int totalC = C1 + C2 + C3 + C4;
    int totalSize = N * totalC * H * W;
    if(index >= totalSize) return;

    int w_ = index % W;
    int tmp = index / W;
    int h_ = tmp % H;
    tmp /= H;
    int c_ = tmp % totalC;
    int n_ = tmp / totalC;

    if(c_ < C1) {
        int idxIn1 = ((n_ * C1 + c_) * H + h_) * W + w_;
        out[index] = in1[idxIn1];
    } else if(c_ < C1 + C2) {
        int cIn2 = c_ - C1;
        int idxIn2 = ((n_ * C2 + cIn2) * H + h_) * W + w_;
        out[index] = in2[idxIn2];
    } else if(c_ < C1 + C2 + C3) {
        int cIn3 = c_ - (C1 + C2);
        int idxIn3 = ((n_ * C3 + cIn3) * H + h_) * W + w_;
        out[index] = in3[idxIn3];
    } else {
        int cIn4 = c_ - (C1 + C2 + C3);
        int idxIn4 = ((n_ * C4 + cIn4) * H + h_) * W + w_;
        out[index] = in4[idxIn4];
    }
}

torch::Tensor cat4d_cuda(
    torch::Tensor in1,
    torch::Tensor in2,
    torch::Tensor in3,
    torch::Tensor in4
) {
    TORCH_CHECK(in1.is_cuda(), "in1 must be a CUDA tensor");
    TORCH_CHECK(in2.is_cuda(), "in2 must be a CUDA tensor");
    TORCH_CHECK(in3.is_cuda(), "in3 must be a CUDA tensor");
    TORCH_CHECK(in4.is_cuda(), "in4 must be a CUDA tensor");

    auto sizes1 = in1.sizes();
    auto N = sizes1[0];
    auto C1 = sizes1[1];
    auto H = sizes1[2];
    auto W = sizes1[3];

    auto C2 = in2.size(1);
    auto C3 = in3.size(1);
    auto C4 = in4.size(1);

    // Output shape: (N, C1+C2+C3+C4, H, W)
    auto outChannels = C1 + C2 + C3 + C4;
    auto out = torch::empty({(long)N, (long)outChannels, (long)H, (long)W}, in1.options());

    int blockSize = 256;
    int gridSize = (N * outChannels * H * W + blockSize - 1) / blockSize;

    cat4d_kernel<<<gridSize, blockSize>>>(
        in1.data_ptr<float>(), in2.data_ptr<float>(),
        in3.data_ptr<float>(), in4.data_ptr<float>(),
        out.data_ptr<float>(),
        N, C1, C2, C3, C4, H, W
    );
    return out;
}
"""

cat4d_cpp_source = r"""
torch::Tensor cat4d_cuda(
    torch::Tensor in1,
    torch::Tensor in2,
    torch::Tensor in3,
    torch::Tensor in4
);
"""

cat4d = load_inline(
    name="cat4d",
    cpp_sources=cat4d_cpp_source,
    cuda_sources=cat4d_cuda_source,
    functions=["cat4d_cuda"],
    verbose=False,
    extra_cflags=[""],
    extra_ldflags=[""],
)

class ModelNew(nn.Module):
    def __init__(self, in_channels, out_1x1, reduce_3x3, out_3x3, reduce_5x5, out_5x5, pool_proj):
        super(ModelNew, self).__init__()

        self.branch1x1 = nn.Conv2d(in_channels, out_1x1, kernel_size=1)

        self.branch3x3 = nn.Sequential(
            nn.Conv2d(in_channels, reduce_3x3, kernel_size=1),
            nn.Conv2d(reduce_3x3, out_3x3, kernel_size=3, padding=1)
        )

        self.branch5x5 = nn.Sequential(
            nn.Conv2d(in_channels, reduce_5x5, kernel_size=1),
            nn.Conv2d(reduce_5x5, out_5x5, kernel_size=5, padding=2)
        )

        self.branch_pool = nn.Sequential(
            nn.MaxPool2d(kernel_size=3, stride=1, padding=1),
            nn.Conv2d(in_channels, pool_proj, kernel_size=1)
        )

        self.cat4d = cat4d

    def forward(self, x):
        branch1x1 = self.branch1x1(x)
        branch3x3 = self.branch3x3(x)
        branch5x5 = self.branch5x5(x)
        branch_pool = self.branch_pool(x)
        return self.cat4d.cat4d_cuda(branch1x1, branch3x3, branch5x5, branch_pool)
